  const j = $json;
  const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]);
  const list = s => s ? '<ul>' + s.split('\n').map(p => '<li>' + esc(p) + '</li>').join('') + '</ul>' : '';
  const en = $('Settings').first().json.invoiceViewLanguage === 'en';
  const t = en
    ? { head: '<b>A mail arrived in the invoice inbox without an invoice file.</b> Often the invoice is only a link to a supplier portal — download it and upload it with the form.', from: 'From', subj: 'Subject', rec: 'Received', links: 'Links that look like an invoice', skipped: 'Attachments that were not processed' }
    : { head: '<b>Im Rechnungspostfach kam eine Mail ohne Rechnungsdatei an.</b> Oft ist die Rechnung nur ein Link auf ein Lieferantenportal – dort herunterladen und über das Formular hochladen.', from: 'Von', subj: 'Betreff', rec: 'Eingang', links: 'Links, die nach einer Rechnung aussehen', skipped: 'Nicht verarbeitete Anhänge' };
  return `<p>${t.head}</p>
<p>${t.from}: ${esc(j.emailFrom)}<br>${t.subj}: ${esc(j.emailSubject)}<br>${t.rec}: ${esc(j.receivedAt)}</p>
${j.links ? '<p><b>' + t.links + '</b></p>' + list(j.links) : ''}${j.skipped ? '<p><b>' + t.skipped + '</b></p>' + list(j.skipped) : ''}`;
})() }}

