// zlib stream (FlateDecode) = 2-byte header + raw deflate + adler32
const inflateZlib = buf => inflateRaw(buf.subarray(2));

// Find every stream whose dictionary marks it as an embedded file, decode it, keep the XML.
function extractEmbeddedXml(pdf) {
  const text = pdf.toString('latin1');
  const found = [];
  const re = /<<((?:(?!>>\s*stream)[\s\S]){0,2000})>>\s*stream\r?\n/g;
  let m;
  while ((m = re.exec(text))) {
    const dict = m[1];
    if (!/\/Type\s*\/EmbeddedFile\b/.test(dict) && !/\/Subtype\s*\/(text#2Fxml|application#2Fxml)/.test(dict)) continue;
    const start = m.index + m[0].length;
    const end = text.indexOf('endstream', start);
    if (end < 0) continue;
    let raw = pdf.subarray(start, end);
    let data;
    try {
      data = /\/FlateDecode/.test(dict) ? inflateZlib(raw) : raw;
    } catch (e) {
      continue;
    }
    const xml = data.toString('utf8').replace(/^﻿/, '').trim();
    if (/<(\w+:)?(CrossIndustryInvoice|CrossIndustryDocument|Invoice|CreditNote)\b/.test(xml)) found.push(xml);
  }
  return found;
}

// XML files are taken as they are; PDFs are searched for an embedded e-invoice (ZUGFeRD / Factur-X).
const out = [];
for (const [i, item] of $input.all().entries()) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const isXml = /\.xml$/i.test(item.json.fileName) || /xml/i.test(item.binary.data.mimeType || '');
  let xml = null, notInvoice = false;
  // FNV-1a fingerprint of the file: duplicates are found even when no invoice number could be read
  let h = 0x811c9dc5;
  for (let k = 0; k < buf.length; k++) h = Math.imul(h ^ buf[k], 16777619) >>> 0;
  const fileHash = h.toString(16).padStart(8, '0') + '-' + buf.length;
  try {
    xml = isXml ? buf.toString('utf8').replace(/^﻿/, '') : (extractEmbeddedXml(buf)[0] || null);
  } catch (e) {
    xml = null;
  }
  if (xml && !/<(\w+:)?(CrossIndustryInvoice|CrossIndustryDocument|Invoice|CreditNote)\b/.test(xml.slice(0, 5000))) notInvoice = true;
  out.push({ json: { ...item.json, hasXml: !!xml, xml, notInvoice, fileHash }, binary: item.binary, pairedItem: i });
}
return out;

// Scans without a text layer, broken PDFs and AI failures still reach a person, never vanish.
const src = $('Find e-invoice XML').item;
const e = $json.error;
const reason = e ? String(typeof e === 'string' ? e : e.message || JSON.stringify(e)).replace(/\s+/g, ' ').slice(0, 200) : '';
return {
  json: { ...src.json, unreadable: reason
    ? 'Could not read this PDF automatically (' + reason + ') — please enter it by hand'
    : 'Scanned PDF without a text layer: needs OCR or manual entry' },
  binary: src.binary,
};

// Bring the AI output into the same shape the XML parser produces, so the same checks run on it.
const o = $json.output || {};
const n = v => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v));
const src = $('Find e-invoice XML').item;
const meta = src.json;
return {
  binary: src.binary,
  json: {
    ...meta,
    aiInvoice: {
      syntax: 'PDF (AI)', profile: '',
      invoiceNumber: o.invoiceNumber || '', typeCode: '', issueDate: o.invoiceDate || '', dueDate: o.dueDate || '',
      paymentTerms: '', currency: o.currency || '', buyerReference: '', orderReference: '',
      seller: { name: o.sellerName || '', vatId: o.sellerVatId || '', taxNumber: '' },
      buyer: { name: o.buyerName || '', vatId: '', taxNumber: '' },
      iban: o.iban || '',
      totals: { lineTotal: null, allowances: 0, charges: 0, taxBasis: n(o.netAmount), tax: n(o.vatAmount),
                grand: n(o.grossAmount), prepaid: 0, rounding: 0, due: n(o.grossAmount) },
      taxBreakdown: [], lines: [],
    },
  },
};

// Parse an EN 16931 e-invoice (CII: ZUGFeRD 2.x / Factur-X / XRechnung-CII, ZUGFeRD 1.0, UBL: XRechnung-UBL / Peppol)
// into one flat structure and run plausibility checks. Pure JavaScript, no external services.

// --- Tiny XML reader: namespace prefixes are dropped, attributes kept ---
function parseXml(xml) {
  const root = { name: '#root', attrs: {}, children: [], text: '' };
  const stack = [root];
  const ent = s => s.replace(/&(lt|gt|amp|quot|apos|#\d+|#x[0-9a-f]+);/gi, (m, e) =>
    e[0] === '#' ? String.fromCodePoint(e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10))
      : { lt: '<', gt: '>', amp: '&', quot: '"', apos: "'" }[e.toLowerCase()]);
  const re = /<!\[CDATA\[([\s\S]*?)\]\]>|<!--[\s\S]*?-->|<\?[\s\S]*?\?>|<!DOCTYPE[^>]*>|<(\/?)([\w.:-]+)((?:\s+[\w.:-]+\s*=\s*(?:"[^"]*"|'[^']*'))*)\s*(\/?)>|([^<]+)/g;
  let m;
  while ((m = re.exec(xml))) {
    const top = stack[stack.length - 1];
    if (m[1] !== undefined) top.text += m[1];
    else if (m[6] !== undefined) top.text += ent(m[6]);
    else if (m[3]) {
      const name = m[3].replace(/^[\w.-]+:/, '');
      if (m[2]) {
        if (stack.length < 2 || top.name !== name) throw new Error(`malformed XML: </${name}> does not close <${top.name}>`);
        stack.pop();
        continue;
      }
      const attrs = {};
      m[4].replace(/([\w.:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g, (_, k, a, b) => { attrs[k.replace(/^[\w.-]+:/, '')] = ent(a ?? b); });
      const node = { name, attrs, children: [], text: '' };
      top.children.push(node);
      if (!m[5]) stack.push(node);
    }
  }
  return root.children[0];
}

// Path lookup: 'A/B|C/D' — '|' gives alternatives for one step (ZUGFeRD 1.0 vs 2.x names).
const all = (node, path) => path.split('/').reduce((nodes, step) => {
  const names = step.split('|');
  return nodes.flatMap(n => n.children.filter(c => names.includes(c.name)));
}, node ? [node] : []);
const one = (node, path) => all(node, path)[0];
const txt = (node, path) => { const n = path ? one(node, path) : node; return n ? n.text.trim() : ''; };
const num = (node, path) => { const t = txt(node, path); return t === '' ? null : Number(t); };
const cdate = s => /^\d{8}$/.test(s) ? `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}` : s;

function normalizeCII(doc) {
  const v1 = doc.name === 'CrossIndustryDocument' || !!one(doc, 'HeaderExchangedDocument'); // incl. 2014 ZUGFeRD drafts with <Invoice> root
  const hdr = one(doc, v1 ? 'HeaderExchangedDocument' : 'ExchangedDocument');
  const tx = one(doc, 'SupplyChainTradeTransaction|SpecifiedSupplyChainTradeTransaction');
  const agr = one(tx, 'ApplicableHeaderTradeAgreement|ApplicableSupplyChainTradeAgreement');
  const set = one(tx, 'ApplicableHeaderTradeSettlement|ApplicableSupplyChainTradeSettlement');
  const sum = one(set, 'SpecifiedTradeSettlementHeaderMonetarySummation|SpecifiedTradeSettlementMonetarySummation');
  const party = p => p && {
    name: txt(p, 'Name'),
    vatId: (all(p, 'SpecifiedTaxRegistration/ID').find(n => n.attrs.schemeID === 'VA') || {}).text?.trim() || '',
    taxNumber: (all(p, 'SpecifiedTaxRegistration/ID').find(n => n.attrs.schemeID === 'FC') || {}).text?.trim() || '',
    street: txt(p, 'PostalTradeAddress/LineOne'),
    postcode: txt(p, 'PostalTradeAddress/PostcodeCode'),
    city: txt(p, 'PostalTradeAddress/CityName'),
    country: txt(p, 'PostalTradeAddress/CountryID'),
    contactName: txt(p, 'DefinedTradeContact/PersonName'),
    phone: txt(p, 'DefinedTradeContact/TelephoneUniversalCommunication/CompleteNumber'),
    email: txt(p, 'DefinedTradeContact/EmailURIUniversalCommunication/URIID') || txt(p, 'URIUniversalCommunication/URIID'),
  };
  // TaxTotalAmount can appear twice (invoice currency + accounting currency)
  const currency = txt(set, 'InvoiceCurrencyCode') || (one(sum, 'GrandTotalAmount') || { attrs: {} }).attrs.currencyID || '';
  const taxTotals = all(sum, 'TaxTotalAmount');
  const taxTotal = taxTotals.find(n => !n.attrs.currencyID || n.attrs.currencyID === currency) || taxTotals[0];
  return {
    syntax: v1 ? 'ZUGFeRD 1.0 (CII)' : 'CII',
    profile: txt(doc, (v1 ? 'SpecifiedExchangedDocumentContext' : 'ExchangedDocumentContext') + '/GuidelineSpecifiedDocumentContextParameter/ID'),
    invoiceNumber: txt(hdr, 'ID'),
    typeCode: txt(hdr, 'TypeCode'),
    issueDate: cdate(txt(hdr, 'IssueDateTime/DateTimeString') || txt(hdr, 'IssueDateTime')),
    dueDate: cdate(txt(set, 'SpecifiedTradePaymentTerms/DueDateDateTime/DateTimeString')),
    deliveryDate: cdate(txt(one(tx, 'ApplicableHeaderTradeDelivery|ApplicableSupplyChainTradeDelivery'), 'ActualDeliverySupplyChainEvent/OccurrenceDateTime/DateTimeString')),
    paymentTerms: txt(set, 'SpecifiedTradePaymentTerms/Description'),
    currency,
    buyerReference: txt(agr, 'BuyerReference'),
    orderReference: txt(agr, 'BuyerOrderReferencedDocument/IssuerAssignedID'),
    seller: party(one(agr, 'SellerTradeParty')),
    buyer: party(one(agr, 'BuyerTradeParty')),
    iban: txt(set, 'SpecifiedTradeSettlementPaymentMeans/PayeePartyCreditorFinancialAccount/IBANID'),
    totals: {
      lineTotal: num(sum, 'LineTotalAmount'),
      allowances: num(sum, 'AllowanceTotalAmount') || 0,
      charges: num(sum, 'ChargeTotalAmount') || 0,
      taxBasis: num(sum, 'TaxBasisTotalAmount'),
      tax: taxTotal ? Number(taxTotal.text.trim()) : null,
      grand: num(sum, 'GrandTotalAmount'),
      prepaid: num(sum, 'TotalPrepaidAmount') || 0,
      rounding: num(sum, 'RoundingAmount') || 0,
      due: num(sum, 'DuePayableAmount'),
    },
    taxBreakdown: all(set, 'ApplicableTradeTax').map(t => ({
      category: txt(t, 'CategoryCode'),
      rate: num(t, 'RateApplicablePercent|ApplicablePercent'),
      basis: num(t, 'BasisAmount'),
      amount: num(t, 'CalculatedAmount'),
    })),
    lines: all(tx, 'IncludedSupplyChainTradeLineItem').map(l => ({
      name: txt(l, 'SpecifiedTradeProduct/Name'),
      quantity: num(l, 'SpecifiedLineTradeDelivery|SpecifiedSupplyChainTradeDelivery/BilledQuantity'),
      unitPrice: num(l, 'SpecifiedLineTradeAgreement|SpecifiedSupplyChainTradeAgreement/NetPriceProductTradePrice/ChargeAmount'),
      net: num(l, 'SpecifiedLineTradeSettlement|SpecifiedSupplyChainTradeSettlement/SpecifiedTradeSettlementLineMonetarySummation|SpecifiedTradeSettlementMonetarySummation/LineTotalAmount'),
      taxRate: num(l, 'SpecifiedLineTradeSettlement|SpecifiedSupplyChainTradeSettlement/ApplicableTradeTax/RateApplicablePercent|ApplicablePercent'),
    })),
  };
}

function normalizeUBL(doc) {
  const credit = doc.name === 'CreditNote';
  const party = p => p && {
    name: txt(p, 'PartyLegalEntity/RegistrationName') || txt(p, 'PartyName/Name'),
    vatId: (all(p, 'PartyTaxScheme').find(s => txt(s, 'TaxScheme/ID') === 'VAT') && txt(all(p, 'PartyTaxScheme').find(s => txt(s, 'TaxScheme/ID') === 'VAT'), 'CompanyID')) || '',
    taxNumber: (all(p, 'PartyTaxScheme').find(s => txt(s, 'TaxScheme/ID') !== 'VAT') && txt(all(p, 'PartyTaxScheme').find(s => txt(s, 'TaxScheme/ID') !== 'VAT'), 'CompanyID')) || '',
    street: txt(p, 'PostalAddress/StreetName'),
    postcode: txt(p, 'PostalAddress/PostalZone'),
    city: txt(p, 'PostalAddress/CityName'),
    country: txt(p, 'PostalAddress/Country/IdentificationCode'),
    contactName: txt(p, 'Contact/Name'),
    phone: txt(p, 'Contact/Telephone'),
    email: txt(p, 'Contact/ElectronicMail') || txt(p, 'EndpointID'),
  };
  const currency = txt(doc, 'DocumentCurrencyCode');
  const taxTotals = all(doc, 'TaxTotal');
  const mainTax = taxTotals.find(t => all(t, 'TaxSubtotal').length) || taxTotals[0];
  const sum = one(doc, 'LegalMonetaryTotal');
  return {
    syntax: 'UBL',
    profile: txt(doc, 'CustomizationID'),
    invoiceNumber: txt(doc, 'ID'),
    typeCode: txt(doc, credit ? 'CreditNoteTypeCode' : 'InvoiceTypeCode'),
    issueDate: txt(doc, 'IssueDate'),
    dueDate: txt(doc, 'DueDate') || txt(doc, 'PaymentMeans/PaymentDueDate'),
    deliveryDate: txt(doc, 'Delivery/ActualDeliveryDate'),
    paymentTerms: txt(doc, 'PaymentTerms/Note'),
    currency,
    buyerReference: txt(doc, 'BuyerReference'),
    orderReference: txt(doc, 'OrderReference/ID'),
    seller: party(one(doc, 'AccountingSupplierParty/Party')),
    buyer: party(one(doc, 'AccountingCustomerParty/Party')),
    iban: txt(doc, 'PaymentMeans/PayeeFinancialAccount/ID'),
    totals: {
      lineTotal: num(sum, 'LineExtensionAmount'),
      allowances: num(sum, 'AllowanceTotalAmount') || 0,
      charges: num(sum, 'ChargeTotalAmount') || 0,
      taxBasis: num(sum, 'TaxExclusiveAmount'),
      tax: mainTax ? num(mainTax, 'TaxAmount') : null,
      grand: num(sum, 'TaxInclusiveAmount'),
      prepaid: num(sum, 'PrepaidAmount') || 0,
      rounding: num(sum, 'PayableRoundingAmount') || 0,
      due: num(sum, 'PayableAmount'),
    },
    taxBreakdown: mainTax ? all(mainTax, 'TaxSubtotal').map(t => ({
      category: txt(t, 'TaxCategory/ID'),
      rate: num(t, 'TaxCategory/Percent'),
      basis: num(t, 'TaxableAmount'),
      amount: num(t, 'TaxAmount'),
    })) : [],
    lines: all(doc, credit ? 'CreditNoteLine' : 'InvoiceLine').map(l => ({
      name: txt(l, 'Item/Name'),
      quantity: num(l, credit ? 'CreditedQuantity' : 'InvoicedQuantity'),
      unitPrice: num(l, 'Price/PriceAmount'),
      net: num(l, 'LineExtensionAmount'),
      taxRate: num(l, 'Item/ClassifiedTaxCategory/Percent'),
    })),
  };
}

function parseInvoice(xml) {
  const doc = parseXml(xml);
  if (!doc) throw new Error('empty XML');
  if (doc.name === 'CrossIndustryInvoice' || doc.name === 'CrossIndustryDocument') return normalizeCII(doc);
  if (one(doc, 'HeaderExchangedDocument')) return normalizeCII(doc);
  if (doc.name === 'Invoice' || doc.name === 'CreditNote') return normalizeUBL(doc);
  throw new Error('not an EN 16931 invoice: <' + doc.name + '>');
}

// --- Plausibility checks (a subset of the EN 16931 business rules, not a full Schematron validation) ---
function ibanValid(iban) {
  const s = iban.replace(/\s+/g, '').toUpperCase();
  if (!/^[A-Z]{2}\d{2}[A-Z0-9]{10,30}$/.test(s)) return false;
  const r = (s.slice(4) + s.slice(0, 4)).replace(/[A-Z]/g, c => String(c.charCodeAt(0) - 55));
  let mod = 0;
  for (const ch of r) mod = (mod * 10 + Number(ch)) % 97;
  return mod === 1;
}

function checkInvoice(inv, today = new Date().toISOString().slice(0, 10)) {
  const problems = [], warnings = [];
  const t = inv.totals;
  const near = (a, b, tol = 0.02) => a !== null && b !== null && Math.abs(a - b) <= tol + 1e-9;
  const money = x => x === null ? '—' : x.toFixed(2);

  for (const [key, label] of [['invoiceNumber', 'invoice number'], ['issueDate', 'issue date'], ['currency', 'currency']])
    if (!inv[key]) problems.push(`Missing ${label}`);
  if (!inv.seller?.name) problems.push('Missing seller name');
  if (!inv.buyer?.name) problems.push('Missing buyer name');
  if (t.grand === null) problems.push('Missing invoice total');
  if (t.due === null && t.grand !== null) t.due = Math.round((t.grand - t.prepaid + t.rounding) * 100) / 100; // optional in ZUGFeRD 1.0 BASIC

  if (inv.lines.length && inv.lines.every(l => l.net !== null) && t.lineTotal !== null) {
    const s = inv.lines.reduce((a, l) => a + (l.net || 0), 0);
    if (!near(s, t.lineTotal)) problems.push(`Sum of line amounts ${money(s)} ≠ line total ${money(t.lineTotal)}`);
  }
  if (t.lineTotal !== null && t.taxBasis !== null && !near(t.lineTotal - t.allowances + t.charges, t.taxBasis))
    problems.push(`Net total ${money(t.taxBasis)} ≠ lines − allowances + charges`);
  if (t.taxBasis !== null && t.tax !== null && t.grand !== null && !near(t.taxBasis + t.tax, t.grand))
    problems.push(`Gross ${money(t.grand)} ≠ net ${money(t.taxBasis)} + VAT ${money(t.tax)}`);
  if (t.grand !== null && t.due !== null && !near(t.grand - t.prepaid + t.rounding, t.due)) {
    if (t.prepaid) problems.push(`Amount due ${money(t.due)} ≠ gross ${money(t.grand)} − prepaid ${money(t.prepaid)}`);
    else problems.push(`Amount due ${money(t.due)} differs from gross ${money(t.grand)} without a stated prepayment — e.g. undeclared prepayment, third-party amounts or a correction; check before paying`);
  }
  if (t.allowances < 0 || t.charges < 0 || t.prepaid < 0)
    problems.push('Allowances, charges and prepaid amounts must not be negative');
  if (Math.abs(t.rounding || 0) > 1) problems.push(`Implausible rounding amount ${money(t.rounding)}`);
  for (const b of inv.taxBreakdown) {
    if (['E', 'AE', 'K', 'G', 'O'].includes(b.category) && b.amount)
      problems.push(`VAT category ${b.category} must have 0.00 VAT, invoice says ${money(b.amount)}`);
    if (b.rate !== null && b.basis !== null && b.amount !== null && !near(b.basis * b.rate / 100, b.amount, 0.01 + Math.abs(b.basis) * 0.0005))
      problems.push(`VAT ${b.rate}% on ${money(b.basis)} should be ${money(b.basis * b.rate / 100)}, invoice says ${money(b.amount)}`);
  }
  if (inv.taxBreakdown.length && t.tax !== null) {
    const s = inv.taxBreakdown.reduce((a, b) => a + (b.amount || 0), 0);
    if (!near(s, t.tax)) problems.push(`VAT breakdown ${money(s)} ≠ VAT total ${money(t.tax)}`);
  }

  if (inv.seller && !inv.seller.vatId && !inv.seller.taxNumber) warnings.push('Seller has neither VAT ID nor tax number (required unless VAT-exempt)');
  if (inv.seller?.vatId && !/^[A-Z]{2}[0-9A-Z+*.]{2,13}$/.test(inv.seller.vatId.replace(/\s+/g, '')))
    warnings.push(`Seller VAT ID looks malformed: ${inv.seller.vatId}`);
  if (inv.seller?.vatId?.startsWith('DE') && !/^DE\d{9}$/.test(inv.seller.vatId.replace(/\s+/g, '')))
    warnings.push(`German VAT ID must be DE + 9 digits: ${inv.seller.vatId}`);
  if (inv.iban && !ibanValid(inv.iban)) problems.push(`IBAN checksum invalid: ${inv.iban}`);
  if (inv.typeCode === '381') warnings.push('Credit note (type 381)');
  if (inv.dueDate && /^\d{4}-\d{2}-\d{2}$/.test(inv.dueDate) && inv.dueDate < today) warnings.push(`Due date ${inv.dueDate} has passed`);

  return { status: problems.length ? 'check' : 'ok', problems, warnings };
}

// Readable PDF view of a parsed e-invoice (the XML stays the legal original).
// Pure JavaScript, no libraries: standard Helvetica fonts, WinAnsi encoding (umlauts, €), A4, page breaks.

const LABELS = {
  de: {
    380: 'Rechnung', 381: 'Gutschrift', 384: 'Rechnungskorrektur', 326: 'Teilrechnung', 389: 'Gutschrift (Selbstfakturierung)',
    from: 'Rechnungssteller', to: 'Rechnungsempfänger', number: 'Rechnungsnummer', date: 'Rechnungsdatum', due: 'Fällig am',
    delivery: 'Leistungsdatum', contact: 'Kontakt',
    buyerRef: 'Käuferreferenz / Leitweg-ID', order: 'Bestellnummer', vatId: 'USt-IdNr.', taxNo: 'Steuernummer',
    pos: 'Pos.', item: 'Bezeichnung', qty: 'Menge', price: 'Einzelpreis', vat: 'USt.', net: 'Netto',
    lineTotal: 'Summe Positionen', allowances: 'Nachlässe', charges: 'Zuschläge', taxBasis: 'Nettobetrag',
    taxTotal: 'Umsatzsteuer', grand: 'Gesamtbetrag', prepaid: 'Bereits gezahlt', payable: 'Zahlbetrag',
    vatOn: 'USt. {rate} % auf {basis}', payment: 'Zahlung', iban: 'IBAN', terms: 'Zahlungsbedingungen',
    footer: 'Lesbare Darstellung der E-Rechnung {file} ({format}). Rechtlich maßgeblich ist die XML-Datei.',
    page: 'Seite {n} von {total}', checks: 'Prüfhinweise',
  },
  en: {
    380: 'Invoice', 381: 'Credit note', 384: 'Corrected invoice', 326: 'Partial invoice', 389: 'Self-billed credit note',
    from: 'Seller', to: 'Buyer', number: 'Invoice number', date: 'Invoice date', due: 'Due date',
    delivery: 'Delivery date', contact: 'Contact',
    buyerRef: 'Buyer reference', order: 'Order number', vatId: 'VAT ID', taxNo: 'Tax number',
    pos: 'Pos.', item: 'Description', qty: 'Qty', price: 'Unit price', vat: 'VAT', net: 'Net',
    lineTotal: 'Sum of lines', allowances: 'Allowances', charges: 'Charges', taxBasis: 'Net total',
    taxTotal: 'VAT total', grand: 'Gross total', prepaid: 'Prepaid', payable: 'Amount due',
    vatOn: 'VAT {rate} % on {basis}', payment: 'Payment', iban: 'IBAN', terms: 'Payment terms',
    footer: 'Readable view of the e-invoice {file} ({format}). The XML file is the legal original.',
    page: 'Page {n} of {total}', checks: 'Check results',
  },
};

// Helvetica widths (1/1000 em) for ASCII 32..126; other characters use 556.
const HELV = [278,278,355,556,556,889,667,191,333,333,389,584,278,333,278,278,556,556,556,556,556,556,556,556,556,556,278,278,584,584,584,556,1015,667,667,722,722,667,611,778,722,278,500,667,556,833,722,778,667,778,722,667,611,722,667,944,667,667,611,278,278,278,469,556,333,556,556,500,556,556,278,556,556,222,222,500,222,833,556,556,556,556,333,500,278,556,500,722,500,500,500,334,260,334,584];
const HELVB = [278,333,474,556,556,889,722,238,333,333,389,584,278,333,278,278,556,556,556,556,556,556,556,556,556,556,333,333,584,584,584,611,975,722,722,722,722,667,611,778,722,278,556,722,611,833,722,778,667,778,722,667,611,722,667,944,667,667,611,333,278,333,584,556,333,556,611,556,611,556,333,611,611,278,278,556,278,889,611,611,611,611,389,556,333,611,556,778,556,556,500,389,280,389,584];

const WIN = { '€': 128, '‚': 130, '„': 132, '…': 133, '–': 150, '—': 151, '‘': 145, '’': 146, '“': 147, '”': 148, '•': 149, '™': 153 };
const winByte = ch => {
  const c = ch.charCodeAt(0);
  if (WIN[ch]) return WIN[ch];
  if (c >= 32 && c <= 126) return c;
  if (c >= 160 && c <= 255) return c;
  return 63; // '?'
};
const textWidth = (s, size, bold) => {
  let w = 0;
  for (const ch of s) { const c = ch.charCodeAt(0); w += (c >= 32 && c <= 126 ? (bold ? HELVB : HELV)[c - 32] : 556); }
  return w * size / 1000;
};
const pdfStr = s => '(' + Array.from(s).map(ch => {
  const b = winByte(ch);
  if (b === 40 || b === 41 || b === 92) return '\\' + String.fromCharCode(b);
  return b > 126 ? '\\' + b.toString(8).padStart(3, '0') : String.fromCharCode(b);
}).join('') + ')';

function wrap(s, width, size, bold) {
  const words = String(s || '').replace(/\s+/g, ' ').trim().split(' ');
  const lines = [];
  let cur = '';
  for (const w of words) {
    const next = cur ? cur + ' ' + w : w;
    if (textWidth(next, size, bold) <= width || !cur) cur = next; else { lines.push(cur); cur = w; }
  }
  if (cur) lines.push(cur);
  return lines.length ? lines : [''];
}

function renderInvoicePdf(inv, opts = {}) {
  const L = LABELS[opts.lang] || LABELS.de;
  const fmt = (v, cur) => v === null || v === undefined || v === '' ? '' :
    Number(v).toLocaleString(opts.lang === 'en' ? 'en-GB' : 'de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + (cur ? ' ' + cur : '');
  const qtyFmt = v => v === null || v === undefined ? '' : Number(v).toLocaleString(opts.lang === 'en' ? 'en-GB' : 'de-DE', { maximumFractionDigits: 4 });
  const cur = inv.currency || '';
  const W = 595, H = 842, M = 50, RIGHT = W - M;
  const pages = [];
  let ops = [], y = 0;

  const text = (s, x, yy, size = 9, bold = false, align = 'left') => {
    s = String(s ?? '');
    if (align === 'right') x -= textWidth(s, size, bold);
    ops.push(`BT /${bold ? 'F2' : 'F1'} ${size} Tf ${x.toFixed(2)} ${yy.toFixed(2)} Td ${pdfStr(s)} Tj ET`);
  };
  const hline = (yy, x1 = M, x2 = RIGHT) => ops.push(`${x1} ${yy.toFixed(2)} m ${x2} ${yy.toFixed(2)} l S`);
  const newPage = () => { if (ops.length) pages.push(ops); ops = ['0.6 w 0.3 0.3 0.3 RG']; y = H - M; };
  const need = (h, inTable) => { if (y - h < M + 40) { newPage(); if (inTable) tableHeader(); } };

  const COLS = { pos: M, item: M + 28, qty: 370, price: 440, vat: 478, net: RIGHT };
  const tableHeader = () => {
    text(L.pos, COLS.pos, y, 8, true); text(L.item, COLS.item, y, 8, true);
    text(L.qty, COLS.qty, y, 8, true, 'right'); text(L.price, COLS.price, y, 8, true, 'right');
    text(L.vat, COLS.vat, y, 8, true, 'right'); text(L.net, COLS.net, y, 8, true, 'right');
    y -= 5; hline(y); y -= 12;
  };

  newPage();
  // Title and invoice meta
  text(L[inv.typeCode] || L[380], M, y, 18, true);
  text(inv.syntax ? inv.syntax : '', RIGHT, y + 4, 7, false, 'right');
  y -= 30;

  const party = (title, p, x) => {
    let yy = y;
    text(title, x, yy, 7, true); yy -= 12;
    if (!p) return yy;
    for (const l of wrap(p.name, 230, 10, true)) { text(l, x, yy, 10, true); yy -= 13; }
    for (const l of [p.street, [p.postcode, p.city].filter(Boolean).join(' '), p.country].filter(Boolean)) { text(l, x, yy); yy -= 11; }
    if (p.vatId) { text(`${L.vatId} ${p.vatId}`, x, yy); yy -= 11; }
    if (p.taxNumber) { text(`${L.taxNo} ${p.taxNumber}`, x, yy); yy -= 11; }
    const c = [p.contactName, p.phone, p.email].filter(Boolean).join(' · ');
    if (c && p === inv.seller) for (const l of wrap(`${L.contact}: ${c}`, 240, 8)) { text(l, x, yy, 8); yy -= 10; }
    return yy;
  };
  const yA = party(L.from, inv.seller, M), yB = party(L.to, inv.buyer, 310);
  y = Math.min(yA, yB) - 14;

  const meta = [[L.number, inv.invoiceNumber], [L.date, inv.issueDate], [L.delivery, inv.deliveryDate], [L.due, inv.dueDate],
    [L.buyerRef, inv.buyerReference], [L.order, inv.orderReference]].filter(([, v]) => v);
  for (const [k, v] of meta) { text(k, M, y, 9, true); text(v, M + 150, y); y -= 12; }
  y -= 12;

  // Line items
  tableHeader();
  inv.lines.forEach((l, i) => {
    const nameLines = wrap(l.name || '', COLS.qty - COLS.item - 45, 9);
    need(nameLines.length * 11 + 4, true);
    text(String(i + 1), COLS.pos, y);
    nameLines.forEach((nl, k) => text(nl, COLS.item, y - k * 11));
    text(qtyFmt(l.quantity), COLS.qty, y, 9, false, 'right');
    text(fmt(l.unitPrice), COLS.price, y, 9, false, 'right');
    text(l.taxRate === null || l.taxRate === undefined ? '' : l.taxRate + ' %', COLS.vat, y, 9, false, 'right');
    text(fmt(l.net), COLS.net, y, 9, false, 'right');
    y -= nameLines.length * 11 + 4;
  });
  y += 4; hline(y); y -= 16;

  // Totals
  const t = inv.totals || {};
  const rows = [[L.lineTotal, t.lineTotal], [L.allowances, t.allowances || null], [L.charges, t.charges || null],
    [L.taxBasis, t.taxBasis],
    ...(inv.taxBreakdown || []).map(b => [L.vatOn.replace('{rate}', b.rate ?? '').replace('{basis}', fmt(b.basis)), b.amount]),
    [L.taxTotal, t.tax], [L.grand, t.grand, true], [L.prepaid, t.prepaid || null], [L.payable, t.due, true]];
  for (const [k, v, bold] of rows) {
    if (v === null || v === undefined) continue;
    need(14);
    text(k, 330, y, 9, !!bold); text(fmt(v, cur), RIGHT, y, 9, !!bold, 'right'); y -= 13;
  }
  y -= 10;

  // Payment and check results
  const block = (title, lines) => {
    lines = lines.filter(Boolean);
    if (!lines.length) return;
    need(16 + lines.length * 11);
    text(title, M, y, 9, true); y -= 12;
    for (const l of lines) for (const w of wrap(l, RIGHT - M, 9)) { need(11); text(w, M, y); y -= 11; }
    y -= 8;
  };
  block(L.payment, [inv.iban && `${L.iban} ${inv.iban}`, inv.paymentTerms && `${L.terms}: ${inv.paymentTerms}`]);

  pages.push(ops);

  // Assemble the PDF file
  const footer = L.footer.replace('{file}', opts.fileName || '').replace('{format}', [inv.syntax, inv.profile].filter(Boolean).join(', '));
  const objs = [];
  const add = s => { objs.push(s); return objs.length; };
  const catalog = add(null), pagesObj = add(null);
  const f1 = add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
  const f2 = add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  const kids = [];
  pages.forEach((p, i) => {
    const foot = [...wrap(footer, 400, 6.5).slice(0, 2).map((fl, k) => `BT /F1 6.5 Tf ${M} ${30 - k * 8} Td ${pdfStr(fl)} Tj ET`),
      `BT /F1 6.5 Tf ${(RIGHT - textWidth(L.page.replace('{n}', i + 1).replace('{total}', pages.length), 6.5)).toFixed(2)} 30 Td ${pdfStr(L.page.replace('{n}', i + 1).replace('{total}', pages.length))} Tj ET`];
    const content = [...p, ...foot].join('\n');
    const bytes = Buffer.from(Array.from(content).map(ch => ch.charCodeAt(0) & 255));
    const c = add({ stream: bytes });
    kids.push(add(`<< /Type /Page /Parent ${pagesObj} 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 ${f1} 0 R /F2 ${f2} 0 R >> >> /Contents ${c} 0 R >>`));
  });
  objs[catalog - 1] = `<< /Type /Catalog /Pages ${pagesObj} 0 R >>`;
  objs[pagesObj - 1] = `<< /Type /Pages /Kids [${kids.map(k => k + ' 0 R').join(' ')}] /Count ${kids.length} >>`;

  const chunks = [Buffer.from('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n', 'latin1')];
  let offset = chunks[0].length;
  const offsets = [];
  objs.forEach((o, i) => {
    offsets.push(offset);
    let buf;
    if (o && o.stream) buf = Buffer.concat([Buffer.from(`${i + 1} 0 obj\n<< /Length ${o.stream.length} >>\nstream\n`, 'latin1'), o.stream, Buffer.from('\nendstream\nendobj\n', 'latin1')]);
    else buf = Buffer.from(`${i + 1} 0 obj\n${o}\nendobj\n`, 'latin1');
    chunks.push(buf); offset += buf.length;
  });
  const xref = `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n` + offsets.map(o => String(o).padStart(10, '0') + ' 00000 n \n').join('') +
    `trailer\n<< /Size ${objs.length + 1} /Root ${catalog} 0 R >>\nstartxref\n${offset}\n%%EOF\n`;
  chunks.push(Buffer.from(xref, 'latin1'));
  return Buffer.concat(chunks);
}

// German texts for every problem / warning line. The checks write English; localize() translates line by line,
// so the stored row, the mails and the approval request use one language (Settings → invoiceViewLanguage).

const DE = [
  [/^Missing invoice number$/, 'Rechnungsnummer fehlt'],
  [/^Missing issue date$/, 'Rechnungsdatum fehlt'],
  [/^Missing currency$/, 'Währung fehlt'],
  [/^Missing seller name$/, 'Name des Lieferanten fehlt'],
  [/^Missing buyer name$/, 'Name des Rechnungsempfängers fehlt'],
  [/^Missing invoice total$/, 'Rechnungsbetrag fehlt'],
  [/^Sum of line amounts (\S+) ≠ line total (\S+)$/, 'Summe der Positionen $1 ≠ Positionssumme $2'],
  [/^Net total (\S+) ≠ lines − allowances \+ charges$/, 'Nettosumme $1 ≠ Positionen − Nachlässe + Zuschläge'],
  [/^Gross (\S+) ≠ net (\S+) \+ VAT (\S+)$/, 'Brutto $1 ≠ Netto $2 + USt $3'],
  [/^Amount due (\S+) ≠ gross (\S+) − prepaid (\S+)$/, 'Zahlbetrag $1 ≠ Brutto $2 − Anzahlung $3'],
  [/^Amount due (\S+) differs from gross (\S+) without a stated prepayment — e\.g\. undeclared prepayment, third-party amounts or a correction; check before paying$/, 'Zahlbetrag $1 weicht von Brutto $2 ab, ohne angegebene Anzahlung – z. B. nicht ausgewiesene Anzahlung, Fremdleistungen oder Korrektur; vor der Zahlung prüfen'],
  [/^VAT (\S+)% on (\S+) should be (\S+), invoice says (\S+)$/, 'USt $1 % auf $2 müsste $3 sein, Rechnung nennt $4'],
  [/^VAT breakdown (\S+) ≠ VAT total (\S+)$/, 'USt-Aufschlüsselung $1 ≠ USt gesamt $2'],
  [/^Seller has neither VAT ID nor tax number \(required unless VAT-exempt\)$/, 'Lieferant ohne USt-IdNr. und Steuernummer (Pflicht, außer bei Steuerbefreiung)'],
  [/^Seller VAT ID looks malformed: (.*)$/, 'USt-IdNr. des Lieferanten sieht fehlerhaft aus: $1'],
  [/^German VAT ID must be DE \+ 9 digits: (.*)$/, 'Deutsche USt-IdNr. muss DE + 9 Ziffern haben: $1'],
  [/^IBAN checksum invalid: (.*)$/, 'IBAN-Prüfsumme ungültig: $1'],
  [/^Credit note \(type 381\)$/, 'Gutschrift (Typ 381)'],
  [/^Due date (\S+) has passed$/, 'Fälligkeit $1 ist überschritten'],
  [/^Allowances, charges and prepaid amounts must not be negative$/, 'Nachlässe, Zuschläge und Anzahlungen dürfen nicht negativ sein'],
  [/^Implausible rounding amount (\S+)$/, 'Unplausibler Rundungsbetrag $1'],
  [/^VAT category (\S+) must have 0\.00 VAT, invoice says (\S+)$/, 'USt-Kategorie $1 muss 0,00 USt haben, Rechnung nennt $2'],
  [/^First IBAN from this supplier — check the bank details once before paying$/, 'Erste IBAN dieses Lieferanten – Bankverbindung vor der Zahlung einmal prüfen'],
  [/^VAT ID \/ tax number (.+) differs from earlier invoices of this supplier \((.+)\)$/, 'USt-IdNr./Steuernummer $1 weicht von früheren Rechnungen dieses Lieferanten ab ($2)'],
  [/^Same invoice also attached as (.+)$/, 'Dieselbe Rechnung ist auch als $1 angehängt'],
  [/^Could not read the e-invoice XML: (.*)$/, 'E-Rechnungs-XML nicht lesbar: $1'],
  [/^This XML file is not an invoice \((.*)\) — please look at it$/, 'Diese XML-Datei ist keine Rechnung ($1) – bitte ansehen'],
  [/^No e-invoice data in this PDF: fields were read by the AI model, please verify$/, 'Keine E-Rechnungsdaten im PDF: Die Felder hat das KI-Modell gelesen – bitte prüfen'],
  [/^Scanned PDF without a text layer: needs OCR or manual entry$/, 'Gescanntes PDF ohne Textebene: OCR oder manuelle Erfassung nötig'],
  [/^Could not read this PDF automatically \((.*)\) — please enter it by hand$/, 'PDF konnte nicht automatisch gelesen werden ($1) – bitte manuell erfassen'],
  [/^Unpacked from (.*)$/, 'Entpackt aus $1'],
  [/^Also in this mail, not processed: (.*)$/, 'Ebenfalls in dieser Mail, nicht verarbeitet: $1'],
  [/^Readable PDF could not be created: (.*)$/, 'Lesbare PDF-Ansicht nicht erstellt: $1'],
  [/^First invoice from this supplier — check the bank details once before paying$/, 'Erste Rechnung dieses Lieferanten – Bankverbindung vor der Zahlung einmal prüfen'],
  [/^Bank details changed: IBAN (.+) was never used by this supplier before \(last: (.+) on invoice (.+)\)\. Confirm by phone on a number you already know — not one from this invoice or email\.$/,
    'Bankverbindung geändert: IBAN $1 wurde von diesem Lieferanten noch nie verwendet (zuletzt: $2 auf Rechnung $3). Telefonisch unter einer Ihnen bekannten Nummer bestätigen – nicht unter einer aus dieser Rechnung oder Mail.'],
  [/^Sent from (\S+), earlier invoices of this supplier came from (.+)$/, 'Gesendet von $1, frühere Rechnungen dieses Lieferanten kamen von $2'],
];
// fragments inside the "not processed" list
const DE_INLINE = [
  [/\(not a PDF, XML or ZIP\)/g, '(kein PDF, XML oder ZIP)'],
  [/\(encrypted\)/g, '(verschlüsselt)'],
  [/\(ZIP could not be opened: /g, '(ZIP nicht lesbar: '],
  [/\(compression method /g, '(Kompressionsverfahren '],
];

function localize(text, lang) {
  if (lang !== 'de' || !text) return text;
  return String(text).split('\n').map(line => {
    for (const [re, rep] of DE) {
      if (!re.test(line)) continue;
      line = line.replace(re, rep);
      // German decimal comma, only in the amount checks (not in file names or VAT IDs)
      if (/^(Summe|Nettosumme|Brutto|Zahlbetrag|USt|Unplausibler)/.test(line)) line = line.replace(/(\d)\.(\d{2})(?!\d)/g, '$1,$2');
      break;
    }
    for (const [re, rep] of DE_INLINE) line = line.replace(re, rep);
    return line;
  }).join('\n');
}

// Input: either the e-invoice XML, or an invoice read by the AI model from a PDF without XML.
const today = $now.toFormat('yyyy-MM-dd');
const lang = $('Settings').first().json.invoiceViewLanguage || 'de';
const clean = s => String(s || '').replace(/\s+/g, '').toUpperCase();
const results = $input.all().map((item, i) => {
  const m = item.json;
  let inv = null, res;
  try {
    if (m.unreadable) throw Object.assign(new Error(m.unreadable), { plain: true });
    inv = m.aiInvoice || parseInvoice(m.xml);
    res = checkInvoice(inv, today);
  } catch (e) {
    inv = null;
    const msg = e.plain ? e.message
      : m.notInvoice ? 'This XML file is not an invoice (' + e.message.split(': ').pop() + ') — please look at it'
      : 'Could not read the e-invoice XML: ' + String(e.message).replace(/\s+/g, ' ');
    res = { status: 'check', problems: [msg], warnings: [] };
  }
  if (m.fromZip) res.warnings.push('Unpacked from ' + m.fromZip);
  if (m.skipped) res.warnings.push('Also in this mail, not processed: ' + m.skipped.split('\n').join('; '));
  if (m.aiInvoice) {
    res.status = 'check';
    res.problems.unshift('No e-invoice data in this PDF: fields were read by the AI model, please verify');
  }
  const t = inv ? inv.totals : {};
  // Files for the emails: the original, plus a readable PDF when the original is a bare XML file
  const binary = {};
  if (item.binary?.data) binary.original = item.binary.data;
  if (inv && !m.aiInvoice && /\.xml$/i.test(m.fileName)) {
    try {
      const pdf = renderInvoicePdf(inv, { lang, fileName: m.fileName });
      binary.view = { data: pdf.toString('base64'), mimeType: 'application/pdf', fileExtension: 'pdf',
                      fileName: m.fileName.replace(/\.xml$/i, '') + (lang === 'de' ? '_lesbar.pdf' : '_readable.pdf') };
    } catch (e) {
      res.warnings.push('Readable PDF could not be created: ' + e.message);
    }
  }
  return {
    pairedItem: i,
    binary,
    json: {
      dedupeKey: inv && inv.invoiceNumber ? clean(inv.seller?.vatId || inv.seller?.taxNumber || inv.seller?.name) + '|' + clean(inv.invoiceNumber) : 'FILE|' + m.fileHash,
      status: res.status,
      source: m.aiInvoice ? 'pdf-ai' : m.unreadable ? 'pdf-unreadable' : 'e-invoice',
      format: inv ? [inv.syntax, inv.profile].filter(Boolean).join(' · ') : '',
      invoiceNumber: inv?.invoiceNumber || '',
      invoiceDate: inv?.issueDate || '',
      dueDate: inv?.dueDate || '',
      sellerName: inv?.seller?.name || '',
      sellerVatId: inv?.seller?.vatId || inv?.seller?.taxNumber || '',
      buyerName: inv?.buyer?.name || '',
      buyerReference: inv?.buyerReference || '',
      currency: inv?.currency || '',
      netAmount: t.taxBasis ?? null,
      vatAmount: t.tax ?? null,
      grossAmount: t.grand ?? null,
      amountDue: t.due ?? null,
      iban: inv?.iban || '',
      lineCount: inv ? inv.lines.length : 0,
      problems: localize(res.problems.join('\n'), lang),
      warnings: localize(res.warnings.join('\n'), lang),
      fileName: m.fileName,
      fileHash: m.fileHash,
      emailFrom: m.emailFrom,
      emailSubject: m.emailSubject,
      receivedAt: m.receivedAt,
    },
  };
});
// The same invoice twice in one run (e.g. XRechnung XML + ZUGFeRD PDF in one mail): keep the first, note the other.
const firstByKey = new Map();
return results.filter(r => {
  const first = firstByKey.get(r.json.dedupeKey);
  if (!first) { firstByKey.set(r.json.dedupeKey, r); return true; }
  const note = localize('Same invoice also attached as ' + r.json.fileName, lang);
  first.json.warnings = [first.json.warnings, note].filter(Boolean).join('\n');
  return false;
});

// The Data Table node returns only the stored row, so take the files back from "Parse & check".
const src = $('Parse & check').all().find(x => x.json.fileHash === $json.fileHash && x.json.fileName === $json.fileName);
const b = (src && src.binary) || {};
return {
  json: {
    ...$json,
    reviewFiles: ['view', 'original'].filter(k => b[k]).join(','),
    forwardFile: b.view ? 'view' : (b.original ? 'original' : ''),
  },
  binary: b,
};

