// Runs when any step of this workflow fails for good (after the retries). Mails fetched by IMAP are
// already marked as read at that point — so say exactly which time window someone has to look at.
const ex = $json.execution || {}, tr = $json.trigger || {};
const err = ex.error || tr.error || {};
const step = ex.lastNodeExecuted || (err.node && err.node.name) || 'trigger';
const at = $now.setZone($('Failure settings').first().json.timezone || 'Europe/Berlin').toFormat('dd.MM.yyyy HH:mm');
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]);
const msg = esc(err.message || '?') + (err.description ? '<br>' + esc(err.description) : '');
const de = ($('Failure settings').first().json.language || 'de') !== 'en';
return [{ json: de ? {
  subject: `E-Rechnung-Workflow abgebrochen bei „${step}“`,
  html: `<p><b>Der E-Rechnung-Workflow ist bei „${esc(step)}“ abgebrochen</b> (${esc(at)}).</p>
<p>Fehler: ${msg}</p>
<p>Rechnungen aus diesem Lauf wurden eventuell nicht geprüft, gespeichert oder weitergeleitet. Mails, die kurz vor ${esc(at)}
eingegangen sind, sind im Rechnungspostfach schon als <b>gelesen</b> markiert – bitte ansehen oder die Dateien über das Formular
hochladen (bereits gespeicherte Rechnungen werden als Dubletten erkannt).</p>
${ex.url ? '<p><a href="' + esc(ex.url) + '">Fehlgeschlagene Ausführung in n8n öffnen</a></p>' : ''}`,
} : {
  subject: `E-invoice workflow failed at "${step}"`,
  html: `<p><b>The e-invoice workflow stopped at "${esc(step)}"</b> (${esc(at)}).</p>
<p>Error: ${msg}</p>
<p>Invoices in this run may not have been checked, stored or forwarded. Mails that arrived shortly before ${esc(at)}
are already marked as <b>read</b> in the invoice inbox — please look at them, or upload the files with the form
(invoices that were already stored are recognised as duplicates).</p>
${ex.url ? '<p><a href="' + esc(ex.url) + '">Open the failed execution in n8n</a></p>' : ''}`,
} }];
